const resolveBinding = `-- name: ResolveBinding :one
SELECT account_id
FROM (
    SELECT identity_id AS account_id
    FROM email_identity_memberships
    WHERE subject_id = $1
    ORDER BY
        CASE role
            WHEN 'owner' THEN 0
            WHEN 'writer' THEN 1
            ELSE 2
        END,
        identity_id
    LIMIT 1
) resolved
`

type ResolveBindingParams struct {
	Subject string
}

func (q *Queries) ResolveBinding(ctx context.Context, arg ResolveBindingParams) (string, error) {
	row := q.db.QueryRow(ctx, resolveBinding, arg.Subject)
	var account_id string
	err := row.Scan(&account_id)
	return account_id, err
}

